css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: var(--loader-size); position: relative; }
.loader::before { content: ''; position: absolute; top: 12%; left: 5%; width: 90%; height: 6%; border-radius: 3px; background: linear-gradient(90deg, var(--accent), var(--accent-2)); }
.loader::after { content: ''; position: absolute; top: 12%; left: 11%; width: 7%; height: 82%; border-radius: 3px; background: var(--accent-2); box-shadow: calc(var(--loader-size) * -.09) calc(var(--loader-size) * .78) 0 0 var(--accent-2), calc(var(--loader-size) * .09) calc(var(--loader-size) * .78) 0 0 var(--accent-2); }
.loader .cable { position: absolute; top: 18%; left: 62%; width: 2.5%; height: 14%; transform-origin: top center; background: #94a3b8; animation: hoist calc(var(--loader-speed) * 2.6) ease-in-out infinite, sway calc(var(--loader-speed) * 1.3) ease-in-out infinite; }
.loader .cable span { position: absolute; top: 100%; left: 50%; width: calc(var(--loader-size) * .2); height: calc(var(--loader-size) * .15); margin-left: calc(var(--loader-size) * -.1); border-radius: 3px; background: linear-gradient(var(--accent), var(--accent-2)); box-shadow: 0 3px 6px rgba(15, 23, 42, .28); }
@keyframes hoist { 0%, 100% { height: 14%; } 50% { height: 54%; } }
@keyframes sway { 0%, 100% { transform: rotate(-5deg); } 50% { transform: rotate(5deg); } }
